/**
 * Coaster rail geometry (WP-C03, BIZ-13): brick-styled rails and studded ties
 * along a route generated by `coaster-design.ts`, as Bedrock entity geometry
 * chunked on the building shell's lattice.
 *
 * OUR OWN GEOMETRY. Round-ish steel bars (two crossed square bars, one rolled
 * 45 degrees about the rail's own axis, which reads as an octagon) and
 * plate-thick ties with one stud at each end. No LEGO coaster track mould is
 * needed or used.
 *
 * WHY CHUNKS. An actor stops drawing about 72 blocks from the camera, measured
 * from its ROOT, and 26.51/26.52 draw nothing farther whatever the declared
 * cull (CLAUDE.md, round 2026-09-26a). A whole-course actor rooted at one
 * point would vanish as a unit, so the course is split on the shell's fixed
 * lattice (`shellCellOf` / `shellCellRoot`): every chunk's root is its cell's
 * centre, and `STATIC_SHELL_CELL_BLOCKS` is sized so a cube whose centre is in
 * the cell stays within `STATIC_SHELL_RADIUS_LIMIT_BLOCKS` of that root even at
 * the largest wand size (`STATIC_SHELL_CULL_MAX_SCALE`). Chunk ids and roots
 * depend on the lattice alone (a changed element elsewhere never renames or
 * moves another chunk), the property the placement runtime's migration relies
 * on. The reach of every chunk is MEASURED from its emitted cubes
 * (`TrackMeshChunk.reachBlocks`) and a chunk past the limit is reported in
 * `TrackMesh.warnings`, never silently kept.
 *
 * FRAMES. Output is in the ROUTE's frame (blocks, +y up, model-local, as
 * `generateCoaster` writes it), which is also written as Bedrock geometry JSON:
 * cube rotations follow `pivotRotation`'s convention (bedrock-geometry-faces.ts,
 * `Rz(-rz) Ry(ry) Rx(-rx)`), so reading the chunks back through
 * `boneTransforms`/`cubeCorners` reproduces the frames built here. If the
 * placement maps the route into the JSON frame by a mirror (the world is the
 * JSON frame mirrored in Z), pass `mirror` so the rotations are solved in the
 * mirrored frame; never mirror the finished geometry (a mirror conjugates every
 * cube rotation). # TODO(C02): decide `mirror` when the route is wired into
 * `coasterRuntimeConfig`.
 *
 * HEIGHT. A route sample is the rail's centreline. The rail bars hang BELOW it
 * (their top faces at the sample plus `railTopOffsetB`, default 0) and the ties
 * under the bars, so a car whose running datum sits on the sample rides on the
 * rail tops. # TODO(C02): confirm the datum against `datumAboveRailTopLdu`.
 *
 * `compareRailRepresentations` is the offline measurement of the alternative
 * (rails as custom block geometry); the decision is recorded in
 * docs/bedrock-addon-guide.md ("Coaster rails: entity chunks or blocks").
 */
import type { CoasterRouteInput, CoasterVec3 } from './coaster-path';
import type { CoasterZone } from './coaster-design';
import {
  STATIC_SHELL_CULL_MAX_SCALE, STATIC_SHELL_RADIUS_LIMIT_BLOCKS,
  shellCellOf, shellCellRoot, shellChunkId, type ShellCell,
} from './bedrock-building-shell';
import { ACTOR_DRAW_CEILING_BLOCKS } from './bedrock-lod-hull';
import { visibleBoundsFor } from './bedrock-placement-pack';
import { SWATCH_SIZE } from './ldraw-entity-atlas';

export type Vec3 = [number, number, number];

// ---------------------------------------------------------------------------
// Profile
// ---------------------------------------------------------------------------

/** The track's dimensions and colours. Lengths in blocks (B) or model units of 1/16 block (U). */
export interface TrackProfile {
  /** Distance between the two rails' centrelines, blocks. */
  gaugeB: number;
  /** Rail bar cross-section edge, units (3.5 = 0.22 block). */
  railU: number;
  /** Height of the rail bars' top face above the route sample, blocks (0: the sample is the rail top). */
  railTopOffsetB: number;
  /** Arc distance between ties, blocks (stretched a hair so a closed route holds a whole number). */
  tieSpacingB: number;
  /** Tie length across the track, blocks; thickness and depth along the track, units. */
  tieWidthB: number; tieThickU: number; tieDepthU: number;
  /** Stud edge and height, units, and its distance from the centreline, blocks (one per tie end). */
  studU: number; studHeightU: number; studOffsetB: number;
  /**
   * Cube budget switches. Each rail is two crossed bars (`roundRails`) and each tie carries two studs (`studs`);
   * turning both off halves-plus the cube count (a device holds ~1-3 kB per cuboid, CLAUDE.md), at the cost of the round, studded look.
   */
  roundRails: boolean; studs: boolean;
  /** Longest rail piece, blocks. A straight is cut this long; a curve is cut shorter. */
  maxSegmentB: number;
  /** Largest distance a rail sample may lie from its piece's chord, blocks. */
  deviationB: number;
  /** LDraw colour ids. `lift`, `launch` and `brake` colour the ties inside those zones. */
  colours: { rail: number; tie: number; stud: number; lift: number; launch: number; brake: number };
}

export const COASTER_TRACK_MESH: Readonly<TrackProfile> = {
  gaugeB: 1.5,
  railU: 3.5,
  railTopOffsetB: 0,
  tieSpacingB: 1,
  tieWidthB: 2.8, tieThickU: 3, tieDepthU: 4,
  studU: 3, studHeightU: 1.5, studOffsetB: 1.1,
  roundRails: true, studs: true,
  maxSegmentB: 1.5,
  deviationB: 0.04,
  // 72 dark bluish grey bars, 71 light bluish grey ties and studs, 25 orange lift ties, 14 yellow launch, 4 red brake.
  colours: { rail: 72, tie: 71, stud: 71, lift: 25, launch: 14, brake: 4 },
};

export interface TrackMeshOptions {
  /** Overrides of `COASTER_TRACK_MESH`. */
  profile?: Partial<TrackProfile>;
  /** The route's zones (arc distance): ties inside a lift, launch or brake take that zone's colour. */
  zones?: readonly CoasterZone[];
  /** Entity id stem of every chunk (`<idPrefix>_c<ix>_<iy>_<iz>`); must not start with a digit. */
  idPrefix?: string;
  /** Mirror an axis of the route before building (see FRAMES above). Default: none. */
  mirror?: 'x' | 'z';
  /** Y of the lattice's floor plane in the route's frame (the ground under the station). Default 0. */
  floorY?: number;
  /** Wand factor the chunks are planned for. Default `STATIC_SHELL_CULL_MAX_SCALE`. */
  maxScale?: number;
}

// ---------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------

/** One Bedrock geometry cube (model units, the chunk's local frame). */
export interface TrackCube {
  origin: Vec3; size: Vec3; pivot: Vec3; rotation: Vec3; uv: [number, number];
}

/** One chunk's geometry of one colour: a flat-colour swatch texture drawn with `ldrawColor`. */
export interface TrackMaterial { geometryId: string; ldrawColor: number; cubes: number }

export interface TrackMeshChunk {
  /** Entity id stem, `shellChunkId(idPrefix, cell)`. */
  id: string;
  cell: ShellCell;
  /** The chunk's root in the route's frame, blocks: the lattice cell's centre. */
  root: Vec3;
  /** Bedrock geometry document (`format_version 1.12.0`), one geometry per colour, cube coordinates local to `root`. */
  geometry: { format_version: '1.12.0'; 'minecraft:geometry': TrackGeometry[] };
  materials: TrackMaterial[];
  cubeCount: number;
  /** Farthest any corner of any cube lies from `root`, blocks at 100 percent. */
  reachBlocks: number;
  /** Rail arc distance covered by the chunk's rail pieces and ties, blocks. */
  arc: [from: number, to: number];
}

export interface TrackGeometry {
  description: { identifier: string; texture_width: number; texture_height: number; visible_bounds_width: number; visible_bounds_height: number; visible_bounds_offset: [number, number, number] };
  bones: Array<{ name: string; pivot: Vec3; cubes: TrackCube[] }>;
}

/** One straight rail piece (before its joint extensions), for continuity checks and renderers. */
export interface TrackRailPiece { rail: 'L' | 'R'; from: Vec3; to: Vec3; index: number }

export interface TrackMesh {
  chunks: TrackMeshChunk[];
  railPieces: TrackRailPiece[];
  stats: {
    routeLengthB: number; railPieces: number; ties: number; cubes: number; chunks: number;
    maxCubesPerChunk: number; maxReachBlocks: number; geometryBytes: number;
  };
  /** Chunks past the reach limit and the like, said rather than dropped. */
  warnings: string[];
}

// ---------------------------------------------------------------------------
// Vector helpers (blocks, tuples)
// ---------------------------------------------------------------------------

const add = (a: readonly number[], b: readonly number[]): Vec3 => [a[0]! + b[0]!, a[1]! + b[1]!, a[2]! + b[2]!];
const sub = (a: readonly number[], b: readonly number[]): Vec3 => [a[0]! - b[0]!, a[1]! - b[1]!, a[2]! - b[2]!];
const mul = (a: readonly number[], k: number): Vec3 => [a[0]! * k, a[1]! * k, a[2]! * k];
const dot = (a: readonly number[], b: readonly number[]): number => a[0]! * b[0]! + a[1]! * b[1]! + a[2]! * b[2]!;
const cross = (a: readonly number[], b: readonly number[]): Vec3 => [a[1]! * b[2]! - a[2]! * b[1]!, a[2]! * b[0]! - a[0]! * b[2]!, a[0]! * b[1]! - a[1]! * b[0]!];
const len = (a: readonly number[]): number => Math.hypot(a[0]!, a[1]!, a[2]!);
const unit = (a: readonly number[]): Vec3 => { const l = len(a); return l < 1e-12 ? [0, 0, 0] : [a[0]! / l, a[1]! / l, a[2]! / l]; };
/** `a` with its component along unit `n` removed, normalised. */
const orthonormal = (a: readonly number[], n: readonly number[]): Vec3 => unit(sub(a, mul(n, dot(a, n))));
const round4 = (v: number): number => Math.round(v * 1e4) / 1e4;
const roundVec = (v: readonly number[]): Vec3 => [round4(v[0]!), round4(v[1]!), round4(v[2]!)];
const RAD = 180 / Math.PI;

/** A right-handed frame: local x = side, y = up, z = along (the cube's own axes). */
interface Frame { side: Vec3; up: Vec3; along: Vec3 }

/** The frame of a segment with unit tangent `t` and a preferred up: `side = up x t`, so `side x up = t`. */
function frameOf(t: Vec3, preferredUp: Vec3): Frame {
  const up = orthonormal(preferredUp, t);
  return { side: unit(cross(up, t)), up, along: t };
}

/** The same frame rolled by `deg` about its own axis (a 45-degree roll turns a square bar into the second half of an octagon). */
function rolled(f: Frame, deg: number): Frame {
  const c = Math.cos(deg / RAD), s = Math.sin(deg / RAD);
  return { side: add(mul(f.side, c), mul(f.up, s)), up: sub(mul(f.up, c), mul(f.side, s)), along: f.along };
}

/**
 * Bedrock cube rotation (degrees, JSON convention `Rz(-rz) Ry(ry) Rx(-rx)` of
 * `pivotRotation`) that turns the cube's local axes onto `f`. Solves
 * `R = Rz(c) Ry(b) Rx(a)` for the matrix whose columns are side, up, along; at
 * the gimbal pole (the side axis vertical: a rail banked 90 degrees) it fixes
 * a = 0.
 */
export function cubeRotationFor(f: Frame): Vec3 {
  const r20 = f.side[2], r21 = f.up[2], r22 = f.along[2], r10 = f.side[1], r00 = f.side[0];
  let a: number, b: number, c: number;
  if (Math.abs(r20) > 1 - 1e-9) {
    b = Math.asin(Math.max(-1, Math.min(1, -r20)));
    a = 0;
    c = Math.atan2(-f.up[0], f.up[1]);
  } else {
    b = Math.asin(-r20);
    a = Math.atan2(r21, r22);
    c = Math.atan2(r10, r00);
  }
  // JSON angles are rx = -a, ry = b, rz = -c.
  return [-a * RAD || 0, b * RAD || 0, -c * RAD || 0];
}

// ---------------------------------------------------------------------------
// Route frames
// ---------------------------------------------------------------------------

interface Sample { p: Vec3; t: Vec3; up: Vec3 }

/** Position, tangent and up per UNIQUE sample (a closed route's repeated seam point dropped). */
function routeSamples(route: CoasterRouteInput, ups: readonly CoasterVec3[], mirror: 'x' | 'z' | undefined): { samples: Sample[]; closed: boolean } {
  const closed = route.kind === 'closed';
  const m = (v: readonly number[]): Vec3 => [mirror === 'x' ? -v[0]! : v[0]!, v[1]!, mirror === 'z' ? -v[2]! : v[2]!];
  const n = closed ? route.points.length - 1 : route.points.length;
  if (n < 2) throw new Error('coaster-track-mesh: a route needs at least two samples.');
  if (ups.length !== route.points.length) throw new Error(`coaster-track-mesh: ${ups.length} ups for ${route.points.length} route points.`);
  const pts = route.points.slice(0, n).map(m);
  const samples: Sample[] = pts.map((p, i) => {
    const prev = closed ? pts[(i - 1 + n) % n]! : pts[Math.max(0, i - 1)]!;
    const next = closed ? pts[(i + 1) % n]! : pts[Math.min(n - 1, i + 1)]!;
    const t = unit(sub(next, prev));
    return { p, t, up: orthonormal(m(ups[i]!), t) };
  });
  return { samples, closed };
}

// ---------------------------------------------------------------------------
// Cubes
// ---------------------------------------------------------------------------

/** A cube before chunking: centre in blocks (route frame), size in units, the frame it is turned to, and its colour. */
interface RawCube { centre: Vec3; sizeU: Vec3; frame: Frame; colour: number; arc: number }

/** Corners of a raw cube, blocks. */
function cornersOf(c: RawCube): Vec3[] {
  const out: Vec3[] = [];
  for (let i = 0; i < 8; i++) {
    const local: Vec3 = [(i & 1 ? 0.5 : -0.5) * c.sizeU[0] / 16, (i & 2 ? 0.5 : -0.5) * c.sizeU[1] / 16, (i & 4 ? 0.5 : -0.5) * c.sizeU[2] / 16];
    out.push(add(c.centre, add(add(mul(c.frame.side, local[0]), mul(c.frame.up, local[1])), mul(c.frame.along, local[2]))));
  }
  return out;
}

// ---------------------------------------------------------------------------
// Rail pieces
// ---------------------------------------------------------------------------

/** Cut points (sample indices, ascending, 0 first and `n` last = 0 again on a closed route) so no piece strays from its samples. */
function cutPoints(samples: readonly Sample[], closed: boolean, offsets: readonly number[], profile: TrackProfile, heightOffsetB: number): number[] {
  const n = samples.length, last = closed ? n : n - 1;
  const at = (i: number): Sample => samples[i % n]!;
  // The offset rail points of sample i: both rails, plus the centreline (a shared cut keeps ties and both rails aligned).
  const railPoint = (i: number, off: number): Vec3 => {
    const s = at(i), side = unit(cross(s.up, s.t));
    return add(add(s.p, mul(side, off)), mul(s.up, heightOffsetB));
  };
  const cuts = [0];
  let i = 0;
  while (i < last) {
    let j = i + 1;
    while (j < last) {
      const k = j + 1;
      let ok = true;
      for (const off of offsets) {
        const a = railPoint(i, off), b = railPoint(k, off), chord = sub(b, a), l = len(chord);
        if (l > profile.maxSegmentB) { ok = false; break; }
        const d = unit(chord);
        for (let m = i + 1; m < k && ok; m++) {
          const rel = sub(railPoint(m, off), a);
          if (len(sub(rel, mul(d, dot(rel, d)))) > profile.deviationB) ok = false;
        }
        if (!ok) break;
      }
      if (!ok) break;
      j = k;
    }
    cuts.push(j);
    i = j;
  }
  return cuts;
}

/** The two rails' pieces and cubes. */
function railCubes(samples: readonly Sample[], closed: boolean, profile: TrackProfile, arcs: readonly number[]): { cubes: RawCube[]; pieces: TrackRailPiece[] } {
  const n = samples.length;
  const half = profile.gaugeB / 2, barB = profile.railU / 16;
  const heightOffsetB = profile.railTopOffsetB - barB / 2;
  const cuts = cutPoints(samples, closed, [-half, half], profile, heightOffsetB);
  const cubes: RawCube[] = [], pieces: TrackRailPiece[] = [];
  const at = (i: number): Sample => samples[i % n]!;
  const pointAt = (i: number, off: number): Vec3 => {
    const s = at(i), side = unit(cross(s.up, s.t));
    return add(add(s.p, mul(side, off)), mul(s.up, heightOffsetB));
  };
  [-half, half].forEach((off, railIndex) => {
    const chords = cuts.slice(0, -1).map((c, k) => unit(sub(pointAt(cuts[k + 1]!, off), pointAt(c, off))));
    cuts.slice(0, -1).forEach((from, k) => {
      const to = cuts[k + 1]!;
      const a = pointAt(from, off), b = pointAt(to, off), chord = sub(b, a), length = len(chord);
      if (length < 1e-9) return;
      const t = chords[k]!;
      // The joint at either end opens a wedge on the outside of a bend: reach into it by half the bar's corner radius times tan(half the turn).
      const jointExtension = (other: Vec3 | undefined): number => {
        if (!other) return 0;
        const cosTurn = Math.max(-1, Math.min(1, dot(t, other)));
        return Math.min(0.5, barB * Math.SQRT1_2 * Math.tan(Math.acos(cosTurn) / 2)) + 0.004;
      };
      const prevChord = k > 0 ? chords[k - 1] : closed ? chords[chords.length - 1] : undefined;
      const nextChord = k < chords.length - 1 ? chords[k + 1] : closed ? chords[0] : undefined;
      const e0 = jointExtension(prevChord), e1 = jointExtension(nextChord);
      // Up for the piece: the mean of its end samples' ups, made square to the chord.
      const upMean = add(at(from).up, at(to).up);
      const frame = frameOf(t, len(upMean) < 1e-6 ? at(from).up : upMean);
      const lengthU = (length + e0 + e1) * 16;
      const centre = add(mul(add(a, b), 0.5), mul(t, (e1 - e0) / 2));
      const arc = arcs[from % n]!;
      const sizeU: Vec3 = [profile.railU, profile.railU, lengthU];
      cubes.push({ centre, sizeU, frame, colour: profile.colours.rail, arc });
      if (profile.roundRails) cubes.push({ centre, sizeU, frame: rolled(frame, 45), colour: profile.colours.rail, arc });
      pieces.push({ rail: railIndex === 0 ? 'L' : 'R', from: a, to: b, index: k });
    });
  });
  return { cubes, pieces };
}

// ---------------------------------------------------------------------------
// Ties
// ---------------------------------------------------------------------------

/** Sample at arc distance `s` of the unique-sample polyline (linear between samples). */
function sampleAt(samples: readonly Sample[], closed: boolean, arcs: readonly number[], total: number, s: number): Sample {
  const n = samples.length;
  let lo = 0, hi = n - 1;
  while (lo < hi - 1) { const mid = (lo + hi) >> 1; if (arcs[mid]! <= s) lo = mid; else hi = mid; }
  const a = samples[lo]!, b = samples[(lo + 1) % n]!;
  const span = (lo + 1 < n ? arcs[lo + 1]! : total) - arcs[lo]!;
  const f = span < 1e-12 ? 0 : Math.max(0, Math.min(1, (s - arcs[lo]!) / span));
  void closed;
  const t = unit(add(mul(a.t, 1 - f), mul(b.t, f)));
  return { p: add(mul(a.p, 1 - f), mul(b.p, f)), t, up: orthonormal(add(mul(a.up, 1 - f), mul(b.up, f)), t) };
}

function tieCubes(samples: readonly Sample[], closed: boolean, arcs: readonly number[], total: number, profile: TrackProfile, zones: readonly CoasterZone[]): { cubes: RawCube[]; ties: number } {
  const count = Math.max(1, Math.round(total / profile.tieSpacingB));
  const step = closed ? total / count : profile.tieSpacingB;
  const barB = profile.railU / 16, thickB = profile.tieThickU / 16;
  const cubes: RawCube[] = [];
  const zoneColour = (s: number): number | undefined => {
    for (const z of zones) {
      if (s < z.from || s > z.to) continue;
      if (z.kind === 'lift') return profile.colours.lift;
      if (z.kind === 'launch') return profile.colours.launch;
      if (z.kind === 'block-brake' || z.kind === 'trim') return profile.colours.brake;
    }
    return undefined;
  };
  // A closed route puts a tie at every step from 0; an open one also closes its far end.
  const ties = closed ? count : Math.floor(total / step) + 1;
  for (let m = 0; m < ties; m++) {
    const s = Math.min(total, m * step);
    const smp = sampleAt(samples, closed, arcs, total, s);
    const frame = frameOf(smp.t, smp.up);
    const top = add(smp.p, mul(frame.up, profile.railTopOffsetB - barB));
    const colour = zoneColour(s) ?? profile.colours.tie;
    cubes.push({ centre: add(top, mul(frame.up, -thickB / 2)), sizeU: [profile.tieWidthB * 16, profile.tieThickU, profile.tieDepthU], frame, colour, arc: s });
    for (const sign of profile.studs ? [-1, 1] : []) {
      const studCentre = add(add(top, mul(frame.side, sign * profile.studOffsetB)), mul(frame.up, profile.studHeightU / 32));
      cubes.push({ centre: studCentre, sizeU: [profile.studU, profile.studHeightU, profile.studU], frame, colour: profile.colours.stud, arc: s });
    }
  }
  return { cubes, ties };
}

// ---------------------------------------------------------------------------
// Chunking and output
// ---------------------------------------------------------------------------

/** The route's cumulative arc per unique sample, and its total length. */
function arcsOf(samples: readonly Sample[], closed: boolean): { arcs: number[]; total: number } {
  const arcs = [0];
  for (let i = 1; i < samples.length; i++) arcs.push(arcs[i - 1]! + len(sub(samples[i]!.p, samples[i - 1]!.p)));
  const total = closed ? arcs[arcs.length - 1]! + len(sub(samples[0]!.p, samples[samples.length - 1]!.p)) : arcs[arcs.length - 1]!;
  return { arcs, total };
}

/**
 * Rails and ties for a generated coaster, chunked on the shell lattice.
 *
 * @param gen the route and its explicit ups (a `GeneratedCoaster`, or any object with those two fields)
 * @throws when the route has fewer than two samples or `ups` is not parallel to it
 */
export function buildTrackMesh(gen: { route: CoasterRouteInput; ups: readonly CoasterVec3[]; zones?: readonly CoasterZone[] }, options: TrackMeshOptions = {}): TrackMesh {
  const profile: TrackProfile = { ...COASTER_TRACK_MESH, ...options.profile, colours: { ...COASTER_TRACK_MESH.colours, ...options.profile?.colours } };
  const idPrefix = options.idPrefix ?? 'coaster_track';
  if (/^\d/.test(idPrefix)) throw new Error(`coaster-track-mesh: entity id stem "${idPrefix}" may not begin with a digit.`);
  const floorY = options.floorY ?? 0, maxScale = options.maxScale ?? STATIC_SHELL_CULL_MAX_SCALE;
  const { samples, closed } = routeSamples(gen.route, gen.ups, options.mirror);
  const { arcs, total } = arcsOf(samples, closed);

  const rails = railCubes(samples, closed, profile, arcs);
  const ties = tieCubes(samples, closed, arcs, total, profile, options.zones ?? gen.zones ?? []);
  const raw = [...rails.cubes, ...ties.cubes];

  // Every cube goes to the lattice cell holding its centre, in a fixed (x, y, z) cell order.
  const cells = new Map<string, { cell: ShellCell; cubes: RawCube[] }>();
  for (const cube of raw) {
    const cell = shellCellOf(cube.centre, floorY), key = cell.join(',');
    const hit = cells.get(key);
    if (hit) hit.cubes.push(cube); else cells.set(key, { cell, cubes: [cube] });
  }
  const ordered = [...cells.values()].sort((a, b) => a.cell[0] - b.cell[0] || a.cell[1] - b.cell[1] || a.cell[2] - b.cell[2]);

  const warnings: string[] = [];
  const limit = STATIC_SHELL_RADIUS_LIMIT_BLOCKS;
  const chunks = ordered.map(({ cell, cubes }): TrackMeshChunk => {
    const id = shellChunkId(idPrefix, cell);
    const root = shellCellRoot(cell, floorY);
    const rootU = mul(root, 16);
    if (rootU.some(v => Math.abs(v - Math.round(v)) > 1e-9)) throw new Error(`${id}: root ${root} is not a whole number of units; the lattice cell must be.`);
    let reach = 0;
    for (const c of cubes) for (const corner of cornersOf(c)) reach = Math.max(reach, len(sub(corner, root)));
    if (reach * maxScale > limit + 1e-9) warnings.push(`${id}: a cube reaches ${(reach * maxScale).toFixed(2)} blocks from the chunk root at ${maxScale}x, past the ${limit}-block limit.`);

    const extent = { min: [Infinity, Infinity, Infinity] as Vec3, max: [-Infinity, -Infinity, -Infinity] as Vec3 };
    for (const c of cubes) for (const corner of cornersOf(c)) for (let a = 0; a < 3; a++) {
      extent.min[a] = Math.min(extent.min[a]!, corner[a]! - root[a]!);
      extent.max[a] = Math.max(extent.max[a]!, corner[a]! - root[a]!);
    }
    const bounds = visibleBoundsFor(extent, 1);

    const byColour = new Map<number, RawCube[]>();
    for (const c of cubes) { const list = byColour.get(c.colour); if (list) list.push(c); else byColour.set(c.colour, [c]); }
    const materials: TrackMaterial[] = [], geometries: TrackGeometry[] = [];
    for (const [colour, list] of [...byColour].sort((a, b) => a[0] - b[0])) {
      const geometryId = `geometry.craftmatic.${id}_${colour}`;
      const out: TrackCube[] = list.map((c): TrackCube => {
        const centreU = sub(mul(c.centre, 16), rootU);
        const origin = sub(centreU, mul(c.sizeU, 0.5));
        return { origin: roundVec(origin), size: roundVec(c.sizeU), pivot: roundVec(centreU), rotation: roundVec(cubeRotationFor(c.frame)), uv: [0, 0] };
      });
      geometries.push({
        description: { identifier: geometryId, texture_width: SWATCH_SIZE, texture_height: SWATCH_SIZE, ...bounds },
        bones: [{ name: 'track', pivot: [0, 0, 0], cubes: out }],
      });
      materials.push({ geometryId, ldrawColor: colour, cubes: out.length });
    }
    const arcsHere = cubes.map(c => c.arc);
    return {
      id, cell, root: root as Vec3, materials, cubeCount: cubes.length, reachBlocks: reach,
      geometry: { format_version: '1.12.0', 'minecraft:geometry': geometries },
      arc: [Math.min(...arcsHere), Math.max(...arcsHere)],
    };
  });

  const geometryBytes = chunks.reduce((n, c) => n + JSON.stringify(c.geometry).length, 0);
  return {
    chunks, railPieces: rails.pieces, warnings,
    stats: {
      routeLengthB: total, railPieces: rails.pieces.length, ties: ties.ties, cubes: raw.length, chunks: chunks.length,
      maxCubesPerChunk: Math.max(0, ...chunks.map(c => c.cubeCount)), maxReachBlocks: Math.max(0, ...chunks.map(c => c.reachBlocks)), geometryBytes,
    },
  };
}

// ---------------------------------------------------------------------------
// Offline comparison: entity chunks against custom block geometry
// ---------------------------------------------------------------------------

/** What the entity route costs and how much of the course a rider has in draw reach. */
export interface EntityRailMeasure {
  chunks: number; cubes: number; maxCubesPerChunk: number; geometryBytes: number;
  /** A rider's draw reach, blocks (an actor is not drawn past it, measured camera to root). */
  drawReachBlocks: number;
  /** Over riders spaced along the course: the share of chunks, and of rail cubes, whose root is within draw reach. */
  visibleChunkShare: { min: number; median: number; mean: number };
  visibleCubeShare: { min: number; median: number; mean: number };
}

/** What the block route would cost at one position quantum. */
export interface BlockRailMeasure {
  /** The quantum the rail's cell crossings are rounded to, units (1/16 block). */
  quantumU: number;
  /** One-block cells the two rails and the ties touch. */
  cellsTouched: number;
  /** Distinct (rail crossings, up, tie phase) shapes, i.e. the custom block permutations the course needs. */
  permutations: number;
  /** Farthest the rounded crossing lies from the true rail, blocks: the discontinuity the rounding leaves at a cell edge. */
  maxEdgeErrorB: number;
}

export interface RailComparison {
  entity: EntityRailMeasure;
  blocks: BlockRailMeasure[];
  /** The documented per-world permutation ceiling (docs/bedrock-addon-guide.md, "The 65,536 cap"). */
  worldPermutationCap: number;
}

const median = (v: number[]): number => { const s = [...v].sort((a, b) => a - b); return s.length ? s[(s.length - 1) >> 1]! : 0; };
const mean = (v: number[]): number => (v.length ? v.reduce((a, b) => a + b, 0) / v.length : 0);

/**
 * The offline half of the entity-versus-block decision. For the entity route:
 * the chunk and cube counts and, from riders spaced `riderSpacingB` along the
 * course, how much of it is inside `ACTOR_DRAW_CEILING_BLOCKS` of the rider.
 * For the block route: rasterise the two rails' centrelines into one-block
 * cells and count the DISTINCT cell contents at several position quanta; every
 * distinct one is a custom block permutation (plus a geometry), and the cell
 * edge forces a rounded crossing there.
 *
 * # TODO(C03): the draw distance of a custom block's geometry (render distance)
 * is documented, not measured; a device round is the only way to confirm it.
 */
export function compareRailRepresentations(
  gen: { route: CoasterRouteInput; ups: readonly CoasterVec3[]; zones?: readonly CoasterZone[] },
  mesh: TrackMesh,
  options: { riderSpacingB?: number; quantaU?: readonly number[]; profile?: Partial<TrackProfile>; mirror?: 'x' | 'z' } = {},
): RailComparison {
  const profile: TrackProfile = { ...COASTER_TRACK_MESH, ...options.profile, colours: { ...COASTER_TRACK_MESH.colours, ...options.profile?.colours } };
  const { samples, closed } = routeSamples(gen.route, gen.ups, options.mirror);
  const { arcs, total } = arcsOf(samples, closed);

  // Entity: a rider every `riderSpacingB` of arc, 1.62 above the rail like a seated head, and the roots in reach.
  const spacing = options.riderSpacingB ?? 4;
  const chunkCubes = mesh.chunks.map(c => c.cubeCount), cubeTotal = chunkCubes.reduce((a, b) => a + b, 0);
  const chunkShare: number[] = [], cubeShare: number[] = [];
  for (let s = 0; s < total; s += spacing) {
    const rider = add(sampleAt(samples, closed, arcs, total, s).p, [0, 1.62, 0]);
    let chunks = 0, cubes = 0;
    mesh.chunks.forEach((c, i) => { if (len(sub(c.root, rider)) <= ACTOR_DRAW_CEILING_BLOCKS) { chunks++; cubes += chunkCubes[i]!; } });
    chunkShare.push(chunks / mesh.chunks.length); cubeShare.push(cubes / cubeTotal);
  }
  const entity: EntityRailMeasure = {
    chunks: mesh.chunks.length, cubes: cubeTotal, maxCubesPerChunk: mesh.stats.maxCubesPerChunk, geometryBytes: mesh.stats.geometryBytes,
    drawReachBlocks: ACTOR_DRAW_CEILING_BLOCKS,
    visibleChunkShare: { min: Math.min(...chunkShare), median: median(chunkShare), mean: mean(chunkShare) },
    visibleCubeShare: { min: Math.min(...cubeShare), median: median(cubeShare), mean: mean(cubeShare) },
  };

  // Blocks: walk each rail's centreline at 1/16-block steps and record, per 1-block cell, the quantised points
  // where the rail enters and leaves, the up vector (1/8) and the ties' arc phases inside it.
  const half = profile.gaugeB / 2, barB = profile.railU / 16;
  const stepB = 1 / 16;
  const quanta = options.quantaU ?? [16, 8, 4, 2, 1];
  const blocks = quanta.map((q): BlockRailMeasure => {
    const shapes = new Set<string>();
    let cellsTouched = 0, maxErr = 0;
    const perCell = new Map<string, string[]>();
    for (const off of [-half, half]) {
      let prevKey = '';
      for (let s = 0; s < total; s += stepB) {
        const smp = sampleAt(samples, closed, arcs, total, s);
        const side = unit(cross(smp.up, smp.t));
        const p = add(add(smp.p, mul(side, off)), mul(smp.up, profile.railTopOffsetB - barB / 2));
        const cell = [Math.floor(p[0]), Math.floor(p[1]), Math.floor(p[2])];
        const key = cell.join(',');
        const local = [p[0] - cell[0]!, p[1] - cell[1]!, p[2] - cell[2]!].map(v => Math.round(v * 16 / q) * q);
        for (let a = 0; a < 3; a++) maxErr = Math.max(maxErr, Math.abs(local[a]! - (p[a]! - cell[a]!) * 16) / 16);
        const up = smp.up.map(v => Math.round(v * 8)).join(',');
        // The shape token: where the rail is in the cell, and which way up. Entry/exit are the first and last tokens of the run.
        const token = `${off < 0 ? 'L' : 'R'}${local.join(',')}u${up}`;
        const list = perCell.get(key);
        if (list) { if (prevKey !== key || list[list.length - 1] !== token) list.push(token); } else perCell.set(key, [token]);
        prevKey = key;
      }
    }
    for (const tokens of perCell.values()) {
      cellsTouched++;
      // Entry and exit of each rail within the cell: the first and last token of each rail's run.
      const byRail = new Map<string, string[]>();
      for (const t of tokens) { const r = t[0]!; const l = byRail.get(r); if (l) l.push(t); else byRail.set(r, [t]); }
      shapes.add([...byRail].sort().map(([r, l]) => `${r}:${l[0]}>${l[l.length - 1]}`).join('|'));
    }
    return { quantumU: q, cellsTouched, permutations: shapes.size, maxEdgeErrorB: maxErr };
  });
  return { entity, blocks, worldPermutationCap: 65536 };
}
